LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
use ieee.std_logic_unsigned.all;
library work;
use work.utilities.all;
 
architecture fsm of morse_transmitter is

   -- Architecture Declarations
   signal opcode: std_logic_vector(7 downto 0);
   signal operand: std_logic_vector(23 downto 0);
   signal ms_ticker: std_logic_vector(19 downto 0);
   signal ms_tick: std_logic;
   signal morse_ticker, morse_speed: std_logic_vector(15 downto 0);
   signal morse_tick: std_logic;
   signal code_length: std_logic_vector(3 downto 0);
   signal code_shr: std_logic_vector(15 downto 0);
   signal cnt: std_logic_vector(2 downto 0);
   signal morse_code_tmp: std_logic;
   
   constant op_speed_c: integer := 1;
   constant op_fcw_c: integer := 2;
   constant op_morsecode_c: integer := 3;
   constant op_break_c: integer := 4;

   type state_type is (
      s_wait,
      s_fetch,
      s_reset,
      s_break,
      s_code0,
      s_code1,
      s_end_char
   );
 
   -- Declare current and next state signals
   signal current_state : state_type;
   signal next_state : state_type;

   -- Declare any pre-registered internal signals
   signal fifo_rd_cld : std_logic ;
   signal morse_fcw_cld : std_logic_vector (26 downto 0);

begin

   -----------------------------------------------------------------
   clocked_proc : process ( 
      clk
   )
   -----------------------------------------------------------------
   begin
      if (clk'event and clk = '1') then
         if (reset = '1') then
            current_state <= s_reset;
            -- Default Reset Values
            fifo_rd_cld <= '0';
            morse_fcw_cld <= conv_std_logic_vector(2400,27);
            morse_speed <= conv_std_logic_vector(150,16);
         else
            current_state <= next_state;
            -- Default Assignment To Internals
            morse_code_tmp <= '0';
            fifo_rd_cld <= '0';

            -- Combined Actions
            case current_state is
               when s_wait => 
                  if ((fifo_size /= 0) and (morse_tick = '1')) then 
                     opcode <= fifo_data(31 downto 24);
                     operand <= fifo_data(23 downto 0);
                     fifo_rd_cld <= '1';
                  end if;
               when s_fetch => 
                  cnt <= "100"; -- add 4 cycles when break
                  if (opcode = op_speed_c) then 
                     if operand(15 downto 0) /= 0 then
                        morse_speed <= operand(15 downto 0);
                     end if;
                  elsif (opcode = op_fcw_c) then 
                     if operand(15 downto 0) /= 0 then
                        morse_fcw_cld <= "000" & operand;
                     end if;
                  elsif (opcode = op_break_c) then 
                  elsif (opcode = op_morsecode_c) then 
                     code_shr <= operand(15 downto 0);
                  end if;
               when s_break => 
                  if morse_tick = '1' then
                     cnt <= cnt - 1;
                  end if;
               when s_code0 => 
                  cnt <= "011"; -- default assignment
                  if code_shr(15) = '1' then
                     if code_shr(14) = '1' then
                         cnt <= "100";
                     else
                         cnt <= "010";
                     end if;
                  end if;
               when s_code1 => 
                  if morse_tick = '1' then
                     cnt <= cnt - 1;
                  end if;
                  if cnt > 1 then
                     morse_code_tmp <= '1';
                  end if;
                  if (morse_tick = '1' and cnt = 1) then 
                     code_shr <= code_shr(13 downto 0) & "00";
                  end if;
               when s_end_char => 
                  if morse_tick = '1' then
                     cnt <= cnt - 1;
                  end if;
               when others =>
                  null;
            end case;
         end if;
      end if;
   end process clocked_proc;
 
   -----------------------------------------------------------------
   nextstate_proc : process ( 
      cnt,
      code_shr,
      current_state,
      fifo_size,
      morse_tick,
      opcode
   )
   -----------------------------------------------------------------
   begin
      case current_state is
         when s_wait => 
            if ((fifo_size /= 0) and (morse_tick = '1')) then 
               next_state <= s_fetch;
            else
               next_state <= s_wait;
            end if;
         when s_fetch => 
            if (opcode = op_speed_c) then 
               next_state <= s_wait;
            elsif (opcode = op_fcw_c) then 
               next_state <= s_wait;
            elsif (opcode = op_break_c) then 
               next_state <= s_break;
            elsif (opcode = op_morsecode_c) then 
               next_state <= s_code0;
            else
               next_state <= s_wait;
            end if;
         when s_reset => 
            next_state <= s_wait;
         when s_break => 
            if (cnt = 0) then 
               next_state <= s_wait;
            else
               next_state <= s_break;
            end if;
         when s_code0 => 
            if (code_shr(15) = '0') then 
               next_state <= s_end_char;
            else
               next_state <= s_code1;
            end if;
         when s_code1 => 
            if (morse_tick = '1' and cnt = 1) then 
               next_state <= s_code0;
            else
               next_state <= s_code1;
            end if;
         when s_end_char => 
            if (morse_tick = '1' and cnt = 1) then 
               next_state <= s_wait;
            else
               next_state <= s_end_char;
            end if;
         when others =>
            next_state <= s_reset;
      end case;
   end process nextstate_proc;
 
   -- Concurrent Statements
   -- Clocked output assignments
   fifo_rd <= fifo_rd_cld;
   morse_fcw <= morse_fcw_cld;
   ---msec ticker ------------------
   process(clk)
   begin
      if rising_edge(clk) then
         if reset = '1' then
            ms_ticker <= (others => '0');
         else
               if ms_tick = '1' then
                   ms_ticker <= (others => '0');
               else
                   ms_ticker <= ms_ticker + 1;
               end if;
         end if;   
      end if;
   end process;
   
   --msec tick assuming 100MHz core clock--
   ms_tick <= '1' when ms_ticker = 100000-1 else '0';
   
   --- morse code speed timer ---------------
   process(clk)
   begin
      if rising_edge(clk) then
         if reset = '1' then
            morse_ticker <= (0 => '1', others => '0');
         elsif ms_tick = '1' then
               if morse_tick = '1' then
                   morse_ticker <= (0=> '1', others => '0');
               else
                   morse_ticker<= morse_ticker + 1;
               end if;
         end if;   
      end if;
   end process;
   
   --morse code speed ticker--
   morse_tick <= ms_tick when morse_ticker = morse_speed else '0';
   
   morse_code <= not morse_code_tmp;
end fsm;
